@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#f4f4f2;--muted:#9ba0a9;--dim:#68717c;--red:#e43b37;--red2:#ff5148;--navy:#0a101a;--mono:'DM Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif;--body:'Manrope',Arial,sans-serif}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#080b11;color:var(--ink);font-family:var(--body)}button{font:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:520px;overflow:hidden;background:#101722}#game-canvas{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(6,9,14,.62) 0%,rgba(7,10,15,.24) 34%,transparent 65%),linear-gradient(0deg,rgba(5,8,13,.48),transparent 25%,rgba(7,10,15,.27) 100%),radial-gradient(ellipse at 50% 45%,transparent 40%,rgba(4,7,12,.37) 100%);z-index:1}.topbar{position:absolute;z-index:4;top:0;left:0;right:0;height:76px;padding:0 40px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.105);background:linear-gradient(180deg,rgba(7,10,15,.72),rgba(7,10,15,.1));letter-spacing:.11em}.brand{display:flex;align-items:center;gap:12px;color:var(--ink);text-decoration:none;font:800 16px var(--display);letter-spacing:.13em}.brand-mark{width:34px;height:34px;border:1px solid var(--red);display:grid;place-items:center;color:#fff;background:var(--red);font:800 22px var(--display);transform:skew(-8deg)}.brand small{display:block;color:#a6abb1;font:9px var(--mono);letter-spacing:.18em;margin-top:3px}.district{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:12px;color:#d4d7da;font:10px var(--mono);letter-spacing:.12em}.district i{height:13px;width:1px;background:#59616b}.district span:last-child{color:#8f97a1}.live-dot,.status-dot{width:6px;height:6px;background:#ed4c43;border-radius:50%;box-shadow:0 0 11px #ed4c43}.top-right{display:flex;align-items:center;gap:20px}.comms{color:#a7acb3;font:9px var(--mono);letter-spacing:.12em;display:flex;align-items:center;gap:8px}.comms b{width:5px;height:5px;border:1px solid var(--red);border-radius:50%}.avatar,.steve-avatar{display:grid;place-items:center;width:34px;height:34px;background:#202733;border:1px solid rgba(255,255,255,.2);font:500 11px var(--mono);color:#e9e9e6}
.mission-card{position:absolute;z-index:3;top:19%;left:5.2%;width:350px;padding:4px 0 0;transition:.45s cubic-bezier(.2,.8,.2,1)}.eyebrow{font:10px var(--mono);letter-spacing:.18em;color:#d6d6d2;display:flex;align-items:center;gap:9px}.eyebrow-line{width:21px;height:1px;background:var(--red)}.mission-code{color:#777f89;margin-left:auto}.mission-card h1{font:900 57px/.82 var(--display);letter-spacing:.015em;margin:19px 0 17px;text-shadow:0 4px 18px #090b10}.mission-card h1 em{font-style:normal;color:var(--red2)}.mission-copy{font-size:12px;line-height:1.75;color:#bdc1c5;max-width:320px;margin:0 0 18px;text-shadow:0 1px 5px #090b10}.mission-meta{height:32px;border-top:1px solid rgba(255,255,255,.16);display:flex;align-items:center;gap:9px;color:#afb5bc;font:9px var(--mono);letter-spacing:.1em}.mission-meta b{color:#f18a60;font-weight:400}.meta-icon{font-size:15px;color:var(--red)}.meta-divider{height:11px;width:1px;background:#646a72;margin:0 3px}.objective{height:57px;background:rgba(13,17,23,.68);border:1px solid rgba(255,255,255,.14);display:flex;align-items:center;padding:0 12px;gap:11px;margin-top:8px;backdrop-filter:blur(8px)}.objective-check{width:24px;height:24px;border:1px solid #59616b;color:#f0574b;font:11px var(--mono);display:grid;place-items:center}.objective b,.objective small{display:block}.objective b{font:600 10px var(--mono);letter-spacing:.1em}.objective small{font:8px var(--mono);letter-spacing:.1em;color:#858d97;margin-top:5px}.objective-arrow{margin-left:auto;color:var(--red);font-size:15px}.deploy-btn{margin-top:16px;width:100%;height:47px;border:0;background:var(--red);color:white;display:flex;align-items:center;justify-content:space-between;padding:0 15px;cursor:pointer;font:700 12px var(--display);letter-spacing:.17em;transition:.2s}.deploy-btn:hover{background:#ff5148;transform:translateY(-2px);box-shadow:0 9px 24px #e43b3733}.btn-arrow{font:16px var(--body)}.mission-foot{margin-top:12px;font:8px var(--mono);color:#838990;letter-spacing:.13em}.mission-foot span{color:var(--red);padding:0 4px}
.comms-card{position:absolute;z-index:3;right:4.7%;bottom:16%;width:285px;padding:13px 15px 11px;border:1px solid rgba(255,255,255,.17);background:rgba(12,16,22,.58);backdrop-filter:blur(10px);box-shadow:0 12px 40px #06090d3d;transition:.4s}.comms-heading{height:20px;display:flex;align-items:center;gap:8px;font:9px var(--mono);letter-spacing:.12em;color:#b6bcc2}.comms-wave{color:var(--red);font-size:13px}.comms-time{margin-left:auto;color:#f07064;font-size:8px}.comms-person{margin-top:10px;display:flex;gap:9px;align-items:center}.steve-avatar{width:30px;height:30px;background:#25323d;color:#abc3cd;border-color:#51616d;font-size:9px}.comms-person b,.comms-person small{display:block}.comms-person b{font:600 9px var(--mono);letter-spacing:.09em}.comms-person small{font:8px var(--mono);color:#7d8790;letter-spacing:.08em;margin-top:3px}.comms-card p{color:#d5d7d6;font-size:11px;line-height:1.5;margin:10px 0 12px}.comms-bars{display:flex;gap:3px;height:8px;align-items:center}.comms-bars i{display:block;width:2px;height:4px;background:#58616b}.comms-bars i:nth-child(3n){height:8px}.comms-bars i:nth-child(2n){height:6px}.comms-bars i:nth-child(-n+5){background:#ba4e48}
.bottom-ui{position:absolute;z-index:3;bottom:0;left:0;right:0;height:42px;padding:0 40px;display:flex;align-items:center;justify-content:space-between;border-top:1px solid rgba(255,255,255,.11);background:rgba(7,10,15,.44);font:8px var(--mono);letter-spacing:.11em;color:#9da4ab}.objective-status{display:flex;align-items:center;gap:9px;color:#d9dcda}.status-dot{width:5px;height:5px}.build-tag{color:#d6d8d6}.build-tag span{color:var(--red);padding:0 4px}.controls-hint{position:absolute;z-index:3;left:50%;bottom:59px;transform:translateX(-50%);padding:10px 13px;background:rgba(11,15,20,.75);border:1px solid rgba(255,255,255,.13);color:#8e969e;font:8px var(--mono);letter-spacing:.06em;white-space:nowrap;backdrop-filter:blur(8px);transition:.3s}.controls-hint span{color:#e4e6e5;border:1px solid #59616a;padding:3px 4px;font-size:8px;margin-right:4px}.controls-hint i{display:inline-block;height:10px;width:1px;background:#515962;margin:0 8px -2px}.hidden{opacity:0;pointer-events:none}.hud{position:absolute;inset:0;z-index:3;pointer-events:none;transition:opacity .35s}.status-panel{position:absolute;top:94px;left:40px;width:275px;padding:10px 12px;background:rgba(9,13,19,.65);border:1px solid rgba(255,255,255,.13);backdrop-filter:blur(8px)}.status-head{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:.1em}.status-live{color:#ed645a;font-size:8px}.health-row,.suit-row{height:24px;display:flex;align-items:center;gap:8px;font:8px var(--mono);color:#969da5}.health-row{margin-top:6px}.health-label{width:38px}.health-track,.suit-track{height:4px;flex:1;background:#353c43}.health-track i,.suit-track i{height:100%;display:block;background:var(--red);width:100%;transition:width .25s}.health-row b,.suit-row b{width:22px;text-align:right;font-size:8px;color:#eee}.suit-track i{background:#6489a3}.encounter-panel{position:absolute;right:40px;top:94px;width:228px;padding:11px 13px;background:rgba(9,13,19,.64);border:1px solid rgba(255,255,255,.13);backdrop-filter:blur(8px)}.encounter-kicker,.enemy-foot{display:flex;justify-content:space-between;font:8px var(--mono);color:#959da5;letter-spacing:.1em}.encounter-kicker span{color:#e86358}.encounter-name{font:20px var(--display);letter-spacing:.07em;margin:4px 0 8px}.encounter-name b{color:#fff}.enemy-health{height:3px;background:#343a41}.enemy-health i{display:block;height:100%;width:100%;background:#df5549;transition:width .25s}.enemy-foot{margin-top:6px;font-size:7px}.objective-hud{position:absolute;top:50%;right:40px;display:flex;align-items:center;gap:10px;padding:10px 12px;background:rgba(8,12,17,.63);border:1px solid rgba(255,255,255,.13);font-family:var(--mono);transform:translateY(-50%)}.objective-hud b,.objective-hud small{display:block}.objective-hud b{font-size:9px;letter-spacing:.09em}.objective-hud small{font-size:8px;color:#9da5ae;margin-top:4px}.target-diamond{font-size:20px;color:var(--red)}.reticle{position:absolute;left:50%;top:50%;width:24px;height:24px;transform:translate(-50%,-50%);opacity:.8}.reticle i,.reticle:before,.reticle:after{position:absolute;content:'';background:#f3f4f0}.reticle i{width:3px;height:3px;border-radius:50%;left:10px;top:10px}.reticle:before{width:1px;height:7px;top:0;left:11px;box-shadow:0 17px #f3f4f0}.reticle:after{height:1px;width:7px;left:0;top:11px;box-shadow:17px 0 #f3f4f0}.sense-flash{position:absolute;inset:0;display:grid;place-items:center;background:radial-gradient(ellipse,transparent 30%,rgba(255,51,43,.16));opacity:0;transition:opacity .08s}.sense-flash span{position:absolute;top:43%;left:50%;color:#ff453c;font:800 46px var(--display);text-shadow:0 0 25px #ff2525;transform:translate(-50%,-50%)}.toast{position:absolute;top:65%;left:50%;transform:translate(-50%,10px);padding:10px 15px;background:#101820;border:1px solid #e34a40;color:#f3f3ef;font:9px var(--mono);letter-spacing:.12em;opacity:0;transition:.3s}.toast.show{opacity:1;transform:translate(-50%,0)}.crosshair-label{position:absolute;z-index:3;top:calc(50% + 24px);left:50%;transform:translateX(-50%);font:8px var(--mono);letter-spacing:.14em;color:#fb776c;opacity:0;transition:.15s}.interaction{position:absolute;z-index:3;left:50%;bottom:91px;transform:translateX(-50%);display:flex;align-items:center;gap:8px;padding:7px 10px;background:rgba(9,13,19,.75);font:8px var(--mono);letter-spacing:.1em;color:#d8dcdd;opacity:0;transition:.2s}.interaction.visible{opacity:1}.keycap{border:1px solid #bbc1c5;padding:4px 6px;color:white}.subtitles{position:absolute;z-index:5;left:50%;bottom:108px;transform:translateX(-50%);padding:7px 11px;background:rgba(6,8,12,.78);font:11px var(--body);color:#eff1ef;white-space:nowrap;opacity:0;transition:opacity .3s}.subtitles.visible{opacity:1}.objective-complete{position:absolute;z-index:6;left:50%;top:50%;transform:translate(-50%,-45%);width:350px;padding:25px;background:rgba(9,13,18,.91);border:1px solid rgba(255,255,255,.22);text-align:center;backdrop-filter:blur(12px);opacity:0;pointer-events:none;transition:.45s}.objective-complete.show{opacity:1;pointer-events:auto;transform:translate(-50%,-50%)}.complete-icon{display:grid;place-items:center;margin:0 auto 13px;width:38px;height:38px;border:1px solid #66a388;border-radius:50%;color:#80c49f;font-size:21px}.objective-complete small,.objective-complete b{display:block}.objective-complete small{font:9px var(--mono);letter-spacing:.16em;color:#80c49f}.objective-complete b{margin-top:7px;font:700 27px var(--display);letter-spacing:.06em}.objective-complete button{margin-top:19px;width:100%;padding:11px 13px;border:1px solid #8a9297;background:transparent;color:#fff;font:10px var(--mono);letter-spacing:.12em;cursor:pointer}.objective-complete button span{float:right;color:#e9574d}.loading{position:absolute;z-index:10;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;background:#090d13;font:9px var(--mono);letter-spacing:.2em;color:#b4bac0;transition:opacity .7s}.loading.done{opacity:0;pointer-events:none}.loading-mark{width:44px;height:44px;display:grid;place-items:center;background:#e43b37;color:#fff;font:800 28px var(--display);transform:skew(-8deg)}.loading i{width:112px;height:1px;background:linear-gradient(90deg,#e43b37 20%,#373f49 20%);animation:loadbar 1.15s ease-in-out infinite alternate}@keyframes loadbar{to{background:linear-gradient(90deg,#e43b37 80%,#373f49 80%)}}
body.started .mission-card{opacity:0;pointer-events:none;transform:translateX(-18px)}body.started .comms-card{opacity:0;transform:translateY(12px);pointer-events:none}body.started .controls-hint{opacity:.82}body.started .bottom-ui{background:rgba(7,10,15,.7)}
@media(max-width:800px){.topbar{padding:0 18px;height:60px}.district{display:none}.mission-card{top:14%;left:22px;width:calc(100% - 44px);max-width:350px}.mission-card h1{font-size:48px}.comms-card{right:18px;bottom:72px;width:250px}.bottom-ui{padding:0 18px}.coords{display:none}.controls-hint{max-width:calc(100% - 20px);overflow:hidden;bottom:12px;left:10px;transform:none;font-size:7px}.controls-hint i{margin:0 4px -2px}.controls-hint span{font-size:7px}.status-panel{left:16px;top:72px;width:230px}.encounter-panel{right:16px;top:72px;width:195px}.objective-hud{right:16px;top:auto;bottom:80px;transform:none}.comms{display:none}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const canvas=document.querySelector('#game-canvas');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0x8795a1);
scene.fog=new THREE.FogExp2(0x8795a1,0.0085);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,420);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.08;
scene.add(new THREE.HemisphereLight(0xb8c6d6,0x26202a,2.1));
const moon=new THREE.DirectionalLight(0xffd5ba,2.2);moon.position.set(-34,55,24);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);moon.shadow.camera.left=-60;moon.shadow.camera.right=60;moon.shadow.camera.top=60;moon.shadow.camera.bottom=-60;scene.add(moon);
const neonLight=new THREE.PointLight(0xd84443,24,85);neonLight.position.set(-10,10,-10);scene.add(neonLight);
const blueLight=new THREE.PointLight(0x4d83bc,22,75);blueLight.position.set(24,12,8);scene.add(blueLight);
const mats={
 road:new THREE.MeshStandardMaterial({color:0x20262d,roughness:.92}),sidewalk:new THREE.MeshStandardMaterial({color:0x555861,roughness:.9}),
 red:new THREE.MeshStandardMaterial({color:0x8e111d,roughness:.58,metalness:.1}),redBright:new THREE.MeshStandardMaterial({color:0xb6242a,roughness:.48,metalness:.12}),
 navy:new THREE.MeshStandardMaterial({color:0x101c35,roughness:.68,metalness:.12}),navyLite:new THREE.MeshStandardMaterial({color:0x192b4a,roughness:.6,metalness:.1}),
 web:new THREE.MeshStandardMaterial({color:0xd9e1df,roughness:.32,metalness:.3}),glow:new THREE.MeshBasicMaterial({color:0xe5473e}),
 concrete:new THREE.MeshStandardMaterial({color:0x41444a,roughness:.88}),metal:new THREE.MeshStandardMaterial({color:0x454c54,roughness:.5,metalness:.6}),
 skin:new THREE.MeshStandardMaterial({color:0x7f452b,roughness:.7}),glass:new THREE.MeshStandardMaterial({color:0x253947,roughness:.25,metalness:.4,emissive:0x101c23}),
 enemy:new THREE.MeshStandardMaterial({color:0x262d34,roughness:.72}),enemyRed:new THREE.MeshStandardMaterial({color:0x692b28,roughness:.6}),enemyGlow:new THREE.MeshStandardMaterial({color:0xff6a48,emissive:0x822617,emissiveIntensity:1.6})
};
const boxGeo=new THREE.BoxGeometry(1,1,1),sphereGeo=new THREE.SphereGeometry(1,16,12),cylGeo=new THREE.CylinderGeometry(1,1,1,12);
function box(parent,mat,pos,scale,cast=true){const m=new THREE.Mesh(boxGeo,mat);m.position.set(...pos);m.scale.set(...scale);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,mat,pos,scale){const m=new THREE.Mesh(sphereGeo,mat);m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;parent.add(m);return m}
function cylinder(parent,mat,pos,rTop,rBot,h,rot=[0,0,0]){const m=new THREE.Mesh(new THREE.CylinderGeometry(rTop,rBot,h,12),mat);m.position.set(...pos);m.rotation.set(...rot);m.castShadow=true;parent.add(m);return m}
function line(parent,points,mat,r=.025){const curve=new THREE.CatmullRomCurve3(points.map(p=>new THREE.Vector3(...p)));const mesh=new THREE.Mesh(new THREE.TubeGeometry(curve,Math.max(8,points.length*5),r,5,false),mat);parent.add(mesh);return mesh}

// Rooftop-to-street block: authored as a compact playable slice of Manhattan.
const city=new THREE.Group();scene.add(city);
box(city,mats.road,[0,-.18,0],[220,.35,220],false);
// roads and curb strips
for(let z=-60;z<=60;z+=30){box(city,mats.concrete,[0,.02,z],[220,.12,7],false);box(city,mats.road,[0,.1,z],[220,.08,5.1],false);for(let x=-100;x<100;x+=10)box(city,new THREE.MeshBasicMaterial({color:0xc2b59b}),[x,.15,z],[4,.018,.12],false)}
for(let x=-60;x<=60;x+=30){box(city,mats.concrete,[x,.02,0],[7,.12,220],false);box(city,mats.road,[x,.1,0],[5.1,.08,220],false)}
// blocks, rooftops, facade grids and warm window lights
const buildingMats=[0x333943,0x45404a,0x37434a,0x504851,0x313d49,0x494447].map(c=>new THREE.MeshStandardMaterial({color:c,roughness:.82}));
const windowMats=[0xd6a969,0x91b9c5,0x2d3942,0xd18d67].map(c=>new THREE.MeshStandardMaterial({color:c,emissive:c,emissiveIntensity:.3,roughness:.45}));
function building(x,z,w,d,h,idx){const g=new THREE.Group();g.position.set(x,0,z);city.add(g);const wall=buildingMats[idx%buildingMats.length];box(g,wall,[0,h/2,0],[w,h,d]);box(g,mats.concrete,[0,h+.25,0],[w+.35,.5,d+.35]);
 for(let y=2.2;y<h-1;y+=2.35){for(let sx=-w/2+1.15;sx<w/2-.4;sx+=2.3){for(const side of [-1,1]){const win=new THREE.Mesh(boxGeo,windowMats[(Math.random()*windowMats.length)|0]);win.position.set(sx,y,side*(d/2+.011));win.scale.set(.82,1.15,.04);g.add(win)}for(let sz=-d/2+1.4;sz<d/2-.4;sz+=2.7){for(const side of [-1,1]){const win=new THREE.Mesh(boxGeo,windowMats[(Math.random()*windowMats.length)|0]);win.position.set(side*(w/2+.011),y,sz);win.scale.set(.04,1.15,.92);g.add(win)}}}}
 // rooftop tanks, vents and a red aviation lamp
 if(h>18){cylinder(g,mats.metal,[w*.18,h+1.5,0],1.3,1.3,2.6);box(g,mats.metal,[-w*.22,h+1,0],[2.5,1.8,2]);sphere(g,mats.glow,[w*.36,h+2,d*.15],[.18,.18,.18])}
 return g}
// Close skyline frames the arena; low rooftops leave clear grapple silhouettes.
building(-16,-28,20,20,31,1);building(17,-29,22,19,43,0);building(-18,1,18,19,24,3);building(17,1,20,19,35,2);
building(-18,32,19,18,29,4);building(18,33,22,20,39,5);building(-46,-18,25,24,57,0);building(46,-17,27,22,63,3);building(-47,25,25,26,48,2);building(47,25,26,25,54,4);
for(let i=0;i<34;i++){const x=(Math.random()-.5)*210,z=(Math.random()-.5)*210;if(Math.abs(x)<53&&Math.abs(z)<48)continue;const w=10+Math.random()*13,d=10+Math.random()*12,h=28+Math.random()*78;building(x,z,w,d,h,i)}
// plaza ground details, lamps, bollards, parked cabs
for(let x=-5;x<=5;x+=5){box(city,mats.metal,[x,.24,7],[.13,.14,18],false)}
function streetLamp(x,z){cylinder(city,mats.metal,[x,2.6,z],.08,.12,5.1);line(city,[[x,5,z],[x+.8,5.1,z],[x+1,4.8,z]],mats.metal,.065);sphere(city,new THREE.MeshBasicMaterial({color:0xffdfa0}),[x+1,4.7,z],[.2,.12,.15]);}
for(const x of [-10,10])for(const z of [-8,8,24])streetLamp(x,z);
function car(x,z,color){const g=new THREE.Group();g.position.set(x,.35,z);city.add(g);const body=new THREE.MeshStandardMaterial({color,roughness:.35,metalness:.45});box(g,body,[0,.42,0],[2, .65,4.1]);box(g,mats.glass,[0,.93,-.2],[1.6,.48,1.8]);for(const wx of [-1,1])for(const wz of [-1.25,1.25]){const wheel=cylinder(g,new THREE.MeshStandardMaterial({color:0x151719}),[wx,.1,wz],.34,.34,.2,[0,0,Math.PI/2]);wheel.rotation.x=Math.PI/2}box(g,new THREE.MeshBasicMaterial({color:0xffe6bc}),[0,.45,-2.07],[1.2,.16,.03]);return g}
car(-8,13,0x293d53);car(8,-13,0x6a2c2d);

// Aoi: fully masked, broad-shouldered silhouette; no exposed skin.
const hero=new THREE.Group();scene.add(hero);hero.position.set(0,0,13);
const torso=new THREE.Group();hero.add(torso);
// hips and tapered, armored trunk
sphere(torso,mats.navy,[0,1.12,0],[.47,.34,.34]);
const chest=box(torso,mats.redBright,[0,1.75,0],[1.12,1.03,.54]);chest.rotation.z=-.035;
box(torso,mats.red,[0,2.12,.01],[1.18,.38,.55]);
// chest spider mark, angular legs
sphere(torso,mats.red,[0,1.88,.286],[.12,.17,.035]);
